schema = {'orders': {'id': 'NUMBER', 'customer': 'VARCHAR2', 'total': 'NUMBER'}}

# v_total orders.total%TYPE  -> steal the column's type
col_type = schema['orders']['total']
value = 49.99

py_to_db = {int: 'NUMBER', float: 'NUMBER', str: 'VARCHAR2'}
value_type = py_to_db[type(value)]

print('total -> ' + col_type)
if value_type == col_type:
    print(f'value {value} matches column type {col_type}')
else:
    print('TYPE MISMATCH')

products = {7: 19.99, 42: 5.00}

# BEGIN ... EXCEPTION ... END, Python edition
try:
    v_price = products[7]
    print('found: ' + str(v_price))
except KeyError:
    print('caught: key 7 missing, using 0 instead')

